create_external_database.code:
import (
	"context"
	"fmt"
	"log"
)

response, err := client.ExternalDatabases().CreateExternalDatabase(context.Background(), map[string]any{
	"external_database": map[string]any{
		"name": "acmedb",
		"tables": []any{
			map[string]any{
				"table_name": "contacts",
				"fields":     []any{"company"},
				"records": []any{
					map[string]any{
						"record": []any{
							map[string]any{"field": "company", "value": "Acme Pty Ltd"},
						},
					},
				},
			},
		},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
fmt.Println(response.Map)

